        li.textContent = 'No links saved yet. Save your first link above.';
        list.appendChild(li);
        return;
      }
      count.textContent = items.length + (items.length === 1 ? ' link saved' : ' links saved');
      for (const it of items) {
        const li = document.createElement('li');
        li.className = 'item';
        const a = document.createElement('a');
        a.href = it.url; a.target = '_blank'; a.rel = 'noopener';
        a.textContent = it.title;
        const url = document.createElement('div');
        url.className = 'url'; url.textContent = it.url;
        const meta = document.createElement('div');
        meta.className = 'meta'; meta.textContent = 'Saved ' + fmt(it.created);
        li.append(a, url, meta);
        list.appendChild(li);
      }
    }

